using Aipms.Net;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<AipmsStore>();
builder.Services.AddSingleton<PasswordService>();
builder.Services.AddSingleton<TokenService>();
builder.Services.AddSingleton<ResumeAnalyzer>();
builder.Services.AddCors(o => o.AddDefaultPolicy(p => p.AllowAnyOrigin().AllowAnyHeader().AllowAnyMethod()));
var app = builder.Build();
app.UseCors(); app.UseDefaultFiles(); app.UseStaticFiles();
var api = app.MapGroup("/api");
api.MapGet("/health", () => new { status = "ok", time = DateTime.UtcNow });

api.MapPost("/auth/register", (RegisterRequest r, AipmsStore db, PasswordService passwords) => db.Write(s =>
{
    var email = r.Email.Trim().ToLowerInvariant();
    if (string.IsNullOrWhiteSpace(email) || string.IsNullOrWhiteSpace(r.Password) || r.Role is not ("student" or "recruiter")) return Api.Fail("email, password and a student/recruiter role are required", 400);
    if (r.Role == "recruiter" && string.IsNullOrWhiteSpace(r.CompanyName)) return Api.Fail("Company name is required", 400);
    if (s.Users.Any(x => x.Email == email)) return Api.Fail("Email already registered", 409);
    var user = new User { Id = AipmsStore.Next(s), Email = email, PasswordHash = passwords.Hash(r.Password), Role = r.Role, IsApproved = r.Role == "student" }; s.Users.Add(user);
    if (r.Role == "student") s.Students.Add(new Student { Id = AipmsStore.Next(s), UserId = user.Id, FullName = r.FullName ?? email.Split('@')[0], EnrollmentNo = r.EnrollmentNo, DepartmentId = r.DepartmentId, Cgpa = r.Cgpa });
    else { var c = s.Companies.FirstOrDefault(x => x.Name.Equals(r.CompanyName!, StringComparison.OrdinalIgnoreCase)); if (c is null) { c = new Company { Id = AipmsStore.Next(s), Name = r.CompanyName!, Location = r.CompanyLocation, Industry = r.CompanyIndustry, Website = r.CompanyWebsite, Description = r.CompanyDescription }; s.Companies.Add(c); } s.Recruiters.Add(new Recruiter { Id = AipmsStore.Next(s), UserId = user.Id, CompanyId = c.Id, FullName = r.FullName ?? email.Split('@')[0], Designation = r.Designation, Phone = r.Phone }); }
    s.AuditLogs.Add(new AuditLog { Id = AipmsStore.Next(s), UserId = user.Id, Action = "REGISTER" });
    return Results.Json(new { message = r.Role == "recruiter" ? "Registered. Your company and account need TPO approval before you can log in." : "Registered successfully.", user = new { id = user.Id, email, role = user.Role } }, statusCode: 201);
}));
api.MapPost("/auth/login", (LoginRequest r, AipmsStore db, PasswordService passwords, TokenService tokens) => db.Write(s =>
{
    var u = s.Users.FirstOrDefault(x => x.Email.Equals(r.Email.Trim(), StringComparison.OrdinalIgnoreCase));
    if (u is null || !passwords.Verify(r.Password, u.PasswordHash)) return Api.Fail("Invalid credentials", 401);
    if (r.Role is not null && r.Role != u.Role) return Api.Fail($"This account is not registered as {r.Role}. Select the correct role and try again.", 401);
    if (!u.IsActive) return Api.Fail("Account has been deactivated", 403); if (!u.IsApproved) return Api.Fail("Account is pending TPO approval", 403);
    s.AuditLogs.Add(new AuditLog { Id = AipmsStore.Next(s), UserId = u.Id, Action = "LOGIN" }); return Results.Json(new { token = tokens.Create(u), user = new { id = u.Id, email = u.Email, role = u.Role } });
}));

api.MapGet("/public/departments", (AipmsStore db) => db.Read(s => s.Departments.OrderBy(x => x.Name).ToList()));
api.MapGet("/public/companies", (AipmsStore db) => db.Read(s => s.Companies.OrderBy(x => x.Name).ToList()));
api.MapGet("/public/skills", (AipmsStore db) => db.Read(s => s.Skills.OrderBy(x => x.Name).ToList()));
api.MapGet("/notifications", (HttpContext c, AipmsStore db, TokenService tokens) => Api.WithUser(c, tokens, u => db.Read(s => Results.Json(s.Notifications.Where(x => x.UserId == u.Id).OrderByDescending(x => x.CreatedAt).Take(50).Select(Api.Notif).ToList()))));
api.MapPost("/notifications/{id:int}/read", (int id, HttpContext c, AipmsStore db, TokenService tokens) => Api.WithUser(c, tokens, u => db.Write(s => { var n = s.Notifications.FirstOrDefault(x => x.Id == id && x.UserId == u.Id); if (n is not null) n.IsRead = true; return Results.Json(new { message = "ok" }); })));
api.MapPost("/notifications/mark-all-read", (HttpContext c, AipmsStore db, TokenService tokens) => Api.WithUser(c, tokens, u => db.Write(s => { foreach (var n in s.Notifications.Where(x => x.UserId == u.Id)) n.IsRead = true; return Results.Json(new { message = "ok" }); })));

api.MapGet("/students/me", (HttpContext c, AipmsStore db, TokenService tokens) => Api.For(c, tokens, "student", u => db.Read(s => { var st = Api.Student(s, u.Id); return st is null ? Api.Fail("Student profile not found", 404) : Results.Json(Api.StudentView(s, st)); })));
api.MapPut("/students/me", (StudentUpdateRequest r, HttpContext c, AipmsStore db, TokenService tokens) => Api.For(c, tokens, "student", u => db.Write(s =>
{
    var st = Api.Student(s, u.Id); if (st is null) return Api.Fail("Student profile not found", 404); st.FullName = r.FullName ?? st.FullName; st.Phone = r.Phone ?? st.Phone; st.Cgpa = r.Cgpa ?? st.Cgpa; st.PassingYear = r.PassingYear ?? st.PassingYear; st.DepartmentId = r.DepartmentId ?? st.DepartmentId; st.Bio = r.Bio ?? st.Bio;
    if (r.SkillNames is not null) { s.StudentSkills.RemoveAll(x => x.StudentId == st.Id); foreach (var raw in r.SkillNames) { var name = raw.Trim().ToLowerInvariant(); if (name.Length == 0) continue; var skill = s.Skills.FirstOrDefault(x => x.Name == name); if (skill is null) { skill = new Skill { Id = AipmsStore.Next(s), Name = name }; s.Skills.Add(skill); } if (!s.StudentSkills.Any(x => x.StudentId == st.Id && x.SkillId == skill.Id)) s.StudentSkills.Add(new StudentSkill { StudentId = st.Id, SkillId = skill.Id }); } }
    return Results.Json(new { message = "Profile updated" });
})));
api.MapPost("/students/resume", async (HttpContext c, AipmsStore db, TokenService tokens, ResumeAnalyzer analyzer, IWebHostEnvironment env) =>
{
    var u = Api.Authorize(c, tokens, "student", out var error); if (error is not null) return error; var form = await c.Request.ReadFormAsync(); var file = form.Files.GetFile("resume"); if (file is null) return Api.Fail("No file uploaded", 400); var ext = Path.GetExtension(file.FileName).ToLowerInvariant(); if (ext is not ".pdf" and not ".docx") return Api.Fail("Only PDF or DOCX files are allowed", 400); if (file.Length > 5 * 1024 * 1024) return Api.Fail("File is too large (maximum is 5MB)", 400);
    var text = await ResumeTextExtractor.ExtractAsync(file); var name = $"{u!.Id}-{Guid.NewGuid():N}{ext}"; var folder = Path.Combine(env.ContentRootPath, "App_Data", "uploads"); Directory.CreateDirectory(folder); await using (var output = File.Create(Path.Combine(folder, name))) await file.CopyToAsync(output);
    return db.Write(s => { var st = Api.Student(s, u.Id)!; foreach (var old in s.Resumes.Where(x => x.StudentId == st.Id)) old.IsActive = false; var resume = new Resume { Id = AipmsStore.Next(s), StudentId = st.Id, Filename = file.FileName, Filepath = name, RawText = text }; s.Resumes.Add(resume); var result = analyzer.Score(text); foreach (var skillName in result.Skills) { var skill = s.Skills.FirstOrDefault(x => x.Name == skillName); if (skill is null) { skill = new Skill { Id = AipmsStore.Next(s), Name = skillName }; s.Skills.Add(skill); } if (!s.StudentSkills.Any(x => x.StudentId == st.Id && x.SkillId == skill.Id)) s.StudentSkills.Add(new StudentSkill { StudentId = st.Id, SkillId = skill.Id }); } s.ResumeAnalyses.Add(new ResumeAnalysis { Id = AipmsStore.Next(s), ResumeId = resume.Id, AtsScore = result.Score, ExtractedSkills = result.Skills, Suggestions = result.Notes }); return Results.Json(new { message = "Resume uploaded and analyzed", resumeId = resume.Id, atsScore = result.Score, extractedSkills = result.Skills, suggestions = result.Notes }, statusCode: 201); });
});
api.MapGet("/students/resume/analysis", (HttpContext c, AipmsStore db, TokenService tokens) => Api.For(c, tokens, "student", u => db.Read(s => { var st = Api.Student(s, u.Id)!; var r = s.Resumes.Where(x => x.StudentId == st.Id && x.IsActive).OrderByDescending(x => x.UploadedAt).FirstOrDefault(); if (r is null) return Api.Fail("No resume uploaded yet", 404); var a = s.ResumeAnalyses.Where(x => x.ResumeId == r.Id).OrderByDescending(x => x.CreatedAt).FirstOrDefault(); return a is null ? Api.Fail("No analysis found", 404) : Results.Json(new { resume = new { id = r.Id, filename = r.Filename, uploadedAt = r.UploadedAt }, atsScore = a.AtsScore, extractedSkills = a.ExtractedSkills, suggestions = a.Suggestions }); })));
api.MapGet("/students/jobs", (HttpContext c, AipmsStore db, TokenService tokens, string? q, string? type, string? location, double? minPackage) => Api.For(c, tokens, "student", _ => db.Read(s => Results.Json(s.Jobs.Where(j => j.IsActive && (q is null || j.Title.Contains(q, StringComparison.OrdinalIgnoreCase) || j.Description.Contains(q, StringComparison.OrdinalIgnoreCase)) && (type is null || j.JobType == type) && (location is null || j.Location.Contains(location, StringComparison.OrdinalIgnoreCase)) && (!minPackage.HasValue || j.SalaryPackage >= minPackage)).OrderByDescending(j => j.PostedAt).Select(j => Api.JobView(s, j)).ToList()))));
api.MapGet("/students/recommendations", (HttpContext c, AipmsStore db, TokenService tokens, ResumeAnalyzer ai) => Api.For(c, tokens, "student", u => db.Read(s => { var st = Api.Student(s, u.Id)!; var skills = Api.Skills(s, st.Id); return Results.Json(s.Jobs.Where(x => x.IsActive).Select(j => { var gap = ai.SkillGap(skills, j.RequiredSkills); return new { job = Api.JobView(s, j), gap.MatchPct, missingSkills = gap.Missing, eligible = !st.Cgpa.HasValue || st.Cgpa >= j.MinCgpa }; }).OrderByDescending(x => x.MatchPct).ThenByDescending(x => x.eligible).Take(20).Select(x => Api.Recommendation(x.job, x.MatchPct, x.missingSkills, x.eligible)).ToList()); })));
api.MapPost("/students/apply/{jobId:int}", (int jobId, HttpContext c, AipmsStore db, TokenService tokens) => Api.For(c, tokens, "student", u => db.Write(s => { var st = Api.Student(s, u.Id)!; var job = s.Jobs.FirstOrDefault(x => x.Id == jobId && x.IsActive); if (job is null) return Api.Fail("Job not found or closed", 404); if (s.Applications.Any(x => x.JobId == jobId && x.StudentId == st.Id)) return Api.Fail("You already applied to this job", 409); var resume = s.Resumes.FirstOrDefault(x => x.StudentId == st.Id && x.IsActive); if (resume is null) return Api.Fail("Upload a resume before applying", 400); var analysis = s.ResumeAnalyses.LastOrDefault(x => x.ResumeId == resume.Id); var a = new Application { Id = AipmsStore.Next(s), JobId = job.Id, StudentId = st.Id, AtsScoreAtApply = analysis?.AtsScore }; s.Applications.Add(a); Api.Notify(s, s.Recruiters.First(x => x.Id == job.RecruiterId).UserId, $"New application received for \"{job.Title}\"", "new_application", null, a.Id); return Results.Json(new { message = "Applied successfully", applicationId = a.Id }, statusCode: 201); })));
api.MapGet("/students/applications", (HttpContext c, AipmsStore db, TokenService tokens) => Api.For(c, tokens, "student", u => db.Read(s => Results.Json(s.Applications.Where(x => x.StudentId == Api.Student(s, u.Id)!.Id).OrderByDescending(x => x.AppliedAt).Select(a => Api.ApplicationView(s, a)).ToList()))));
api.MapGet("/students/queries", (HttpContext c, AipmsStore db, TokenService tokens) => Api.For(c, tokens, "student", u => db.Read(s => Results.Json(s.StudentQueries.Where(x => x.StudentId == Api.Student(s, u.Id)!.Id).OrderByDescending(x => x.CreatedAt).ToList()))));
api.MapPost("/students/queries", (QueryRequest r, HttpContext c, AipmsStore db, TokenService tokens) => Api.For(c, tokens, "student", u => db.Write(s => { if (string.IsNullOrWhiteSpace(r.Message)) return Api.Fail("message required", 400); var st = Api.Student(s, u.Id)!; var q = new StudentQuery { Id = AipmsStore.Next(s), StudentId = st.Id, Subject = r.Subject, Message = r.Message }; s.StudentQueries.Add(q); foreach (var t in s.Users.Where(x => x.Role == "tpo" && x.IsActive)) Api.Notify(s, t.Id, $"New query from {st.FullName}", "new_query", r.Message, q.Id); return Results.Json(new { message = "Query submitted", id = q.Id }, statusCode: 201); })));

api.MapGet("/recruiters/me", (HttpContext c, AipmsStore db, TokenService tokens) => Api.For(c, tokens, "recruiter", u => db.Read(s => { var r = s.Recruiters.FirstOrDefault(x => x.UserId == u.Id); return r is null ? Api.Fail("Recruiter profile not found", 404) : Results.Json(new { r.Id, r.UserId, r.CompanyId, full_name = r.FullName, r.Designation, r.Phone, company = r.CompanyId is null ? null : s.Companies.First(x => x.Id == r.CompanyId) }); })));
api.MapPost("/recruiters/jobs", (JobRequest r, HttpContext c, AipmsStore db, TokenService tokens) => Api.For(c, tokens, "recruiter", u => db.Write(s => { if (string.IsNullOrWhiteSpace(r.Title)) return Api.Fail("title is required", 400); var recruiter = s.Recruiters.First(x => x.UserId == u.Id); var job = new Job { Id = AipmsStore.Next(s), RecruiterId = recruiter.Id, Title = r.Title, Description = r.Description ?? "", JobType = r.JobType ?? "Full-Time", Location = r.Location ?? "", SalaryPackage = r.SalaryPackage, MinCgpa = r.MinCgpa ?? 0, RequiredSkills = r.RequiredSkills ?? [], Deadline = r.Deadline }; s.Jobs.Add(job); return Results.Json(new { message = "Job posted", jobId = job.Id }, statusCode: 201); })));
api.MapGet("/recruiters/jobs", (HttpContext c, AipmsStore db, TokenService tokens) => Api.For(c, tokens, "recruiter", u => db.Read(s => { var r = s.Recruiters.First(x => x.UserId == u.Id); return Results.Json(s.Jobs.Where(x => x.RecruiterId == r.Id).OrderByDescending(x => x.PostedAt).Select(j => new { j.Id, recruiter_id = j.RecruiterId, j.Title, description = j.Description, job_type = j.JobType, j.Location, salary_package = j.SalaryPackage, min_cgpa = j.MinCgpa, required_skills = string.Join(", ", j.RequiredSkills), deadline = j.Deadline, posted_at = j.PostedAt, is_active = j.IsActive, applicantCount = s.Applications.Count(a => a.JobId == j.Id) }).ToList()); })));
api.MapPut("/recruiters/jobs/{id:int}/close", (int id, HttpContext c, AipmsStore db, TokenService tokens) => Api.For(c, tokens, "recruiter", u => db.Write(s => { var r = s.Recruiters.First(x => x.UserId == u.Id); var j = s.Jobs.FirstOrDefault(x => x.Id == id && x.RecruiterId == r.Id); if (j is not null) j.IsActive = false; return Results.Json(new { message = "Job closed" }); })));
api.MapGet("/recruiters/jobs/{id:int}/applicants", (int id, HttpContext c, AipmsStore db, TokenService tokens, ResumeAnalyzer ai) => Api.For(c, tokens, "recruiter", u => db.Read(s => { var r = s.Recruiters.First(x => x.UserId == u.Id); var j = s.Jobs.FirstOrDefault(x => x.Id == id && x.RecruiterId == r.Id); if (j is null) return Api.Fail("Job not found", 404); return Results.Json(s.Applications.Where(x => x.JobId == id).Select(a => Api.ApplicantView(s, a, j, ai)).OrderByDescending(x => (x.ats_score_at_apply ?? 0) + x.matchPct).ToList()); })));
api.MapPut("/recruiters/applications/{id:int}/status", (int id, StatusRequest r, HttpContext c, AipmsStore db, TokenService t) => Api.For(c, t, "recruiter", u => db.Write(s => { var a = s.Applications.FirstOrDefault(x => x.Id == id); var valid = new[] { "Applied", "Shortlisted", "Interview Scheduled", "Selected", "Rejected" }; if (a is null || !valid.Contains(r.Status)) return Api.Fail("Application not found or status invalid", 400); var job = s.Jobs.First(x => x.Id == a.JobId); if (s.Recruiters.First(x => x.Id == job.RecruiterId).UserId != u.Id) return Api.Fail("Application not found", 404); a.Status = r.Status!; Api.Notify(s, s.Students.First(x => x.Id == a.StudentId).UserId, $"Your application for \"{job.Title}\" is now \"{a.Status}\"", "status_update", null, a.Id); return Results.Json(new { message = "Status updated" }); })));
api.MapPost("/recruiters/applications/{id:int}/interview", (int id, InterviewRequest r, HttpContext c, AipmsStore db, TokenService t) => Api.For(c, t, "recruiter", u => db.Write(s => { var a = s.Applications.FirstOrDefault(x => x.Id == id); if (a is null) return Api.Fail("Application not found", 404); var job = s.Jobs.First(x => x.Id == a.JobId); if (s.Recruiters.First(x => x.Id == job.RecruiterId).UserId != u.Id) return Api.Fail("Application not found", 404); var i = s.Interviews.FirstOrDefault(x => x.ApplicationId == id); if (i is null) { i = new Interview { Id = AipmsStore.Next(s), ApplicationId = id }; s.Interviews.Add(i); } i.ScheduledAt = r.ScheduledAt; i.Mode = r.Mode ?? "Online"; a.Status = "Interview Scheduled"; Api.Notify(s, s.Students.First(x => x.Id == a.StudentId).UserId, $"Interview scheduled for \"{job.Title}\"", "interview", $"Scheduled for {i.ScheduledAt} · Mode: {i.Mode}", a.Id); return Results.Json(new { message = "Interview scheduled" }); })));
api.MapPost("/recruiters/applications/{id:int}/offer", (int id, OfferRequest r, HttpContext c, AipmsStore db, TokenService t) => Api.For(c, t, "recruiter", u => db.Write(s => { var a = s.Applications.FirstOrDefault(x => x.Id == id); if (a is null) return Api.Fail("Application not found", 404); var job = s.Jobs.First(x => x.Id == a.JobId); if (s.Recruiters.First(x => x.Id == job.RecruiterId).UserId != u.Id) return Api.Fail("Application not found", 404); var i = s.Interviews.FirstOrDefault(x => x.ApplicationId == id); if (i is null) return Api.Fail("Schedule an interview first", 400); i.Status = "Completed"; var o = s.OfferLetters.FirstOrDefault(x => x.InterviewId == i.Id); if (o is null) { o = new OfferLetter { Id = AipmsStore.Next(s), InterviewId = i.Id }; s.OfferLetters.Add(o); } o.Package = r.PackageAmount; o.JoiningDate = r.JoiningDate; a.Status = "Selected"; Api.Notify(s, s.Students.First(x => x.Id == a.StudentId).UserId, $"Congratulations! You received an offer for \"{job.Title}\"", "offer", $"Package: ₹{r.PackageAmount} · Joining: {r.JoiningDate}", o.Id); return Results.Json(new { message = "Offer issued" }); })));
api.MapPost("/students/offers/{id:int}/respond", (int id, OfferResponseRequest r, HttpContext c, AipmsStore db, TokenService t) => Api.For(c, t, "student", u => db.Write(s => { if (r.Response is not ("Accepted" or "Rejected" or "Negotiating")) return Api.Fail("response must be Accepted, Rejected, or Negotiating", 400); var o = s.OfferLetters.FirstOrDefault(x => x.Id == id); if (o is null) return Api.Fail("Offer not found", 404); var i = s.Interviews.First(x => x.Id == o.InterviewId); var a = s.Applications.First(x => x.Id == i.ApplicationId); var st = Api.Student(s, u.Id); if (st is null || a.StudentId != st.Id) return Api.Fail("Offer not found", 404); o.Response = r.Response; o.ResponseMessage = r.Message; o.RespondedAt = DateTime.UtcNow; if (r.Response == "Rejected") a.Status = "Rejected"; return Results.Json(new { message = "Response recorded" }); })));

// TPO and administrator: the same management data is exposed to the preserved frontend.
api.MapGet("/tpo/pending-recruiters", (HttpContext c, AipmsStore db, TokenService t) => Api.For(c, t, new[] { "tpo", "admin" }, _ => db.Read(s => Results.Json(s.Recruiters.Where(r => !s.Users.First(u => u.Id == r.UserId).IsApproved).Select(r => { var co = r.CompanyId is null ? null : s.Companies.First(x => x.Id == r.CompanyId); return new { r.Id, full_name = r.FullName, r.Designation, r.Phone, email = s.Users.First(u => u.Id == r.UserId).Email, is_approved = false, companyId = co?.Id, companyName = co?.Name, companyLocation = co?.Location, companyIndustry = co?.Industry, companyWebsite = co?.Website, companyDescription = co?.Description }; }).ToList()))));
api.MapPost("/tpo/recruiters/{id:int}/approve", (int id, HttpContext c, AipmsStore db, TokenService t) => Api.For(c, t, new[] { "tpo", "admin" }, _ => db.Write(s => { var r = s.Recruiters.FirstOrDefault(x => x.Id == id); if (r is null) return Api.Fail("Recruiter not found", 404); s.Users.First(x => x.Id == r.UserId).IsApproved = true; if (r.CompanyId is int company) s.Companies.First(x => x.Id == company).IsVerified = true; return Results.Json(new { message = "Recruiter approved" }); })));
api.MapGet("/tpo/students", (HttpContext c, AipmsStore db, TokenService t) => Api.For(c, t, new[] { "tpo", "admin" }, _ => db.Read(s => Results.Json(s.Students.OrderBy(x => x.FullName).Select(st => new { st.Id, full_name = st.FullName, enrollment_no = st.EnrollmentNo, st.Cgpa, email = s.Users.First(u => u.Id == st.UserId).Email, is_active = s.Users.First(u => u.Id == st.UserId).IsActive, department = st.DepartmentId is null ? null : s.Departments.First(d => d.Id == st.DepartmentId).Name }).ToList()))));
api.MapGet("/tpo/reports", (HttpContext c, AipmsStore db, TokenService t) => Api.For(c, t, new[] { "tpo", "admin" }, _ => db.Read(s => { var placed = s.Applications.Where(x => x.Status == "Selected").Select(x => x.StudentId).Distinct().Count(); return Results.Json(new { totalStudents = s.Students.Count, totalRecruiters = s.Recruiters.Count, totalJobs = s.Jobs.Count, totalApplications = s.Applications.Count, placed, placementRate = s.Students.Count == 0 ? 0 : (int)Math.Round(100d * placed / s.Students.Count), avgAtsScore = s.ResumeAnalyses.Count == 0 ? null : (int?)Math.Round(s.ResumeAnalyses.Average(x => x.AtsScore)), byStatus = s.Applications.GroupBy(x => x.Status).Select(g => new { status = g.Key, c = g.Count() }) }); })));
api.MapGet("/admin/users", (HttpContext c, AipmsStore db, TokenService t) => Api.For(c, t, "admin", _ => db.Read(s => Results.Json(s.Users.OrderByDescending(x => x.CreatedAt).Select(u => new { u.Id, u.Email, u.Role, is_active = u.IsActive, is_approved = u.IsApproved, created_at = u.CreatedAt }).ToList()))));
api.MapGet("/admin/system-stats", (HttpContext c, AipmsStore db, TokenService t) => Api.For(c, t, "admin", _ => db.Read(s => Results.Json(new { users = s.Users.Count, students = s.Students.Count, recruiters = s.Recruiters.Count, companies = s.Companies.Count, jobs = s.Jobs.Count, applications = s.Applications.Count, resumes = s.Resumes.Count }))));

app.MapFallbackToFile("index.html"); app.Run();

static class Api
{
    public static IResult Fail(string error, int code) => Results.Json(new { error }, statusCode: code);
    public static UserSession? Authorize(HttpContext c, TokenService tokens, string role, out IResult? error) { var u = tokens.Validate(c.Request.Headers.Authorization); error = u is null ? Fail("Missing auth token", 401) : u.Role != role ? Fail("Forbidden: insufficient role", 403) : null; return error is null ? u : null; }
    public static IResult WithUser(HttpContext c, TokenService tokens, Func<UserSession, IResult> action) { var u = tokens.Validate(c.Request.Headers.Authorization); return u is null ? Fail("Missing auth token", 401) : action(u); }
    public static IResult For(HttpContext c, TokenService tokens, string role, Func<UserSession, IResult> action) => For(c, tokens, new[] { role }, action);
    public static IResult For(HttpContext c, TokenService tokens, string[] roles, Func<UserSession, IResult> action) { var u = tokens.Validate(c.Request.Headers.Authorization); return u is null ? Fail("Missing auth token", 401) : !roles.Contains(u.Role) ? Fail("Forbidden: insufficient role", 403) : action(u); }
    public static Student? Student(DatabaseState s, int userId) => s.Students.FirstOrDefault(x => x.UserId == userId);
    public static List<string> Skills(DatabaseState s, int studentId) => s.StudentSkills.Where(x => x.StudentId == studentId).Select(x => s.Skills.First(k => k.Id == x.SkillId).Name).ToList();
    public static void Notify(DatabaseState s, int uid, string message, string type, string? detail, int? refId) => s.Notifications.Add(new Notification { Id = AipmsStore.Next(s), UserId = uid, Message = message, Type = type, Detail = detail, ReferenceId = refId });
    public static object Notif(Notification n) => new { n.Id, user_id = n.UserId, n.Message, n.Type, n.Detail, reference_id = n.ReferenceId, is_read = n.IsRead, created_at = n.CreatedAt };
    public static object StudentView(DatabaseState s, Student st) => new { st.Id, user_id = st.UserId, full_name = st.FullName, enrollment_no = st.EnrollmentNo, department_id = st.DepartmentId, st.Cgpa, st.Phone, passing_year = st.PassingYear, st.Bio, department = st.DepartmentId is null ? null : s.Departments.FirstOrDefault(x => x.Id == st.DepartmentId)?.Name, skills = s.StudentSkills.Where(x => x.StudentId == st.Id).Select(x => s.Skills.First(k => k.Id == x.SkillId)), activeResume = s.Resumes.Where(x => x.StudentId == st.Id && x.IsActive).OrderByDescending(x => x.UploadedAt).FirstOrDefault() };
    public static object JobView(DatabaseState s, Job j) { var r = s.Recruiters.First(x => x.Id == j.RecruiterId); return new { j.Id, recruiter_id = j.RecruiterId, j.Title, description = j.Description, job_type = j.JobType, j.Location, salary_package = j.SalaryPackage, min_cgpa = j.MinCgpa, required_skills = string.Join(", ", j.RequiredSkills), deadline = j.Deadline, posted_at = j.PostedAt, is_active = j.IsActive, recruiterName = r.FullName, companyName = r.CompanyId is null ? null : s.Companies.FirstOrDefault(x => x.Id == r.CompanyId)?.Name }; }
    public static object Recommendation(object job, int match, List<string> missing, bool eligible) { var result = job.GetType().GetProperties().ToDictionary(p => p.Name, p => p.GetValue(job)); result["matchPct"] = match; result["missingSkills"] = missing; result["eligible"] = eligible; return result; }
    public static object ApplicationView(DatabaseState s, Application a) { var j = s.Jobs.First(x => x.Id == a.JobId); var r = s.Recruiters.First(x => x.Id == j.RecruiterId); var i = s.Interviews.FirstOrDefault(x => x.ApplicationId == a.Id); var o = i is null ? null : s.OfferLetters.FirstOrDefault(x => x.InterviewId == i.Id); return new { a.Id, job_id = a.JobId, student_id = a.StudentId, a.Status, ats_score_at_apply = a.AtsScoreAtApply, applied_at = a.AppliedAt, j.Title, job_type = j.JobType, j.Location, companyName = r.CompanyId is null ? null : s.Companies.FirstOrDefault(x => x.Id == r.CompanyId)?.Name, scheduled_at = i?.ScheduledAt, interview_mode = i?.Mode, interview_status = i?.Status, offer_id = o?.Id, offer_package = o?.Package, joining_date = o?.JoiningDate, offer_response = o?.Response, offer_response_message = o?.ResponseMessage }; }
    public static dynamic ApplicantView(DatabaseState s, Application a, Job j, ResumeAnalyzer ai) { var st = s.Students.First(x => x.Id == a.StudentId); var gap = ai.SkillGap(Skills(s, st.Id), j.RequiredSkills); return new { a.Id, job_id = a.JobId, student_id = st.Id, a.Status, ats_score_at_apply = a.AtsScoreAtApply, applied_at = a.AppliedAt, full_name = st.FullName, enrollment_no = st.EnrollmentNo, st.Cgpa, department = st.DepartmentId is null ? null : s.Departments.First(x => x.Id == st.DepartmentId).Name, studentSkills = Skills(s, st.Id), matchPct = gap.MatchPct, missingSkills = gap.Missing }; }
}
